insert into public.cat_paket (paket, kod, surum, onayli, veri) values ('sinav', 'lgs', 1, false, $ritos${"kod": "LGS", "testler": [{"test": "Sözel Bölüm", "soru": 50, "dersler": [{"ders": "Türkçe", "soru": 20}, {"ders": "T.C. İnkılap Tarihi ve Atatürkçülük", "soru": 10}, {"ders": "Din Kültürü ve Ahlak Bilgisi", "soru": 10}, {"ders": "İngilizce", "soru": 10}]}, {"test": "Sayısal Bölüm", "soru": 40, "dersler": [{"ders": "Matematik", "soru": 20}, {"ders": "Fen Bilimleri", "soru": 20}]}], "dersler": [{"id": "lgs-turkce", "ad": "Türkçe", "uniteler": [{"ad": "Sözcükte anlam", "konular": [{"id": "lgs-turkce.gercek-mecaz-ve-terim-anlam", "ad": "Gerçek, mecaz ve terim anlam"}, {"id": "lgs-turkce.sozcukler-arasi-anlam-iliskileri", "ad": "Sözcükler arası anlam ilişkileri"}, {"id": "lgs-turkce.deyimler-atasozleri-ve-ozdeyisler", "ad": "Deyimler, atasözleri ve özdeyişler"}, {"id": "lgs-turkce.baglamdan-anlam-cikarma", "ad": "Bağlamdan anlam çıkarma"}]}, {"ad": "Cümlede anlam", "konular": [{"id": "lgs-turkce.cumle-yorumlama-ve-cikarim", "ad": "Cümle yorumlama ve çıkarım"}, {"id": "lgs-turkce.cumlede-anlam-iliskileri-neden-sonuc-amac-sonuc-", "ad": "Cümlede anlam ilişkileri (neden-sonuç, amaç-sonuç, koşul)"}, {"id": "lgs-turkce.oznel-ve-nesnel-anlatim", "ad": "Öznel ve nesnel anlatım"}, {"id": "lgs-turkce.gecis-ve-baglanti-ifadeleri", "ad": "Geçiş ve bağlantı ifadeleri"}]}, {"ad": "Paragrafta anlam", "konular": [{"id": "lgs-turkce.konu-ve-ana-dusunce", "ad": "Konu ve ana düşünce"}, {"id": "lgs-turkce.yardimci-dusunceler", "ad": "Yardımcı düşünceler"}, {"id": "lgs-turkce.paragrafin-yapisi-cumle-siralama-akisi-bozan-cum", "ad": "Paragrafın yapısı (cümle sıralama, akışı bozan cümle)"}, {"id": "lgs-turkce.anlatim-bicimleri", "ad": "Anlatım biçimleri"}, {"id": "lgs-turkce.dusunceyi-gelistirme-yollari", "ad": "Düşünceyi geliştirme yolları"}, {"id": "lgs-turkce.hikaye-unsurlari", "ad": "Hikâye unsurları"}, {"id": "lgs-turkce.metin-karsilastirma-ve-cikarim", "ad": "Metin karşılaştırma ve 